const D30 = [
{ id:'lobster-roll', c:'na', lat:43.661, lon:-70.255, base:4, prep:20, cook:10, diff:1, tags:['sea','fast','street'],
  art:{v:'board',bg:'#2f2a20',plate:'#e9dcc0',style:'roll',food:['#c2452c','#e0dcc0','#4f8f4a'],garnish:'#7fae6a'},
  n:{fr:'Lobster roll',en:'Lobster roll'},
  p:{fr:'Portland, Maine, États-Unis',en:'Portland, Maine, USA'},
  d:{fr:"De la chair de homard fraîchement décortiquée, à peine liée de mayonnaise ou simplement de beurre fondu selon les écoles, entassée dans un petit pain à hot-dog grillé sur les côtés, sandwich estival emblématique du Maine.",
     en:"Freshly shelled lobster meat, barely bound with mayonnaise or simply melted butter depending on the school of thought, piled into a hot-dog bun toasted on the sides, an emblematic summer sandwich of Maine."
     },
  i:[['lobster',900,'g'],['mayonnaise',80,'ml'],['celery',1,'stalk'],['lemon',1,'pc'],['butter',40,'g'],['hoagie_roll',4,'pc'],['chives',1,'bunch']],
  s:{fr:["Faites cuire le homard à l'eau bouillante salée 10 minutes, laissez refroidir puis décortiquez.","Coupez la chair en gros morceaux réguliers.","Mélangez délicatement avec mayonnaise, céleri finement haché et un filet de citron.","Faites griller les pains beurrés sur leurs deux faces coupées jusqu'à dorés.","Garnissez généreusement chaque pain de chair de homard, parsemez de ciboulette et servez immédiatement."],
     en:["Cook the lobster in salted boiling water 10 minutes, let cool then shell.","Cut the meat into large even chunks.","Gently mix with mayonnaise, finely chopped celery and a squeeze of lemon.","Toast the buttered buns on both cut sides until golden.","Generously fill each bun with lobster meat, scatter with chives and serve immediately."]
     } },

{ id:'buffalo-wings', c:'na', lat:42.886, lon:-78.878, base:6, prep:15, cook:25, diff:1, tags:['fry','poultry','spicy'],
  art:{v:'board',bg:'#2a2028',plate:'#e9dcc0',style:'other',food:['#c2452c','#e0a83a','#e0dcc0'],garnish:'#7fae6a'},
  n:{fr:'Ailes de Buffalo',en:'Buffalo wings'},
  p:{fr:'Buffalo, État de New York, États-Unis',en:'Buffalo, New York State, USA'},
  d:{fr:"Des ailes de poulet frites nature puis noyées dans une sauce brûlante au beurre et au piment, nées en 1964 dans un bar de Buffalo pour caser un arrivage imprévu, servies avec bâtonnets de céleri et sauce au bleu pour tempérer le feu.",
     en:"Chicken wings fried plain then drowned in a scorching butter and hot sauce, born in 1964 at a Buffalo bar to use up an unexpected delivery, served with celery sticks and blue cheese dip to temper the heat."
     },
  i:[['chicken_wings',1.2,'kg'],['hot_sauce',150,'ml'],['butter',100,'g'],['celery',4,'stalk'],['blue_cheese',150,'g'],['sour_cream',100,'ml'],['frying_oil',1,'l']],
  s:{fr:["Séchez soigneusement les ailes de poulet, faites-les frire dans l'huile chaude 12 minutes jusqu'à bien dorées et croustillantes.","Faites fondre le beurre, mélangez-le à la sauce piquante encore chaud pour émulsionner.","Égouttez les ailes frites, plongez-les dans la sauce brûlante en remuant pour bien les enrober.","Préparez la sauce au bleu en mélangeant fromage bleu émietté, crème smetana et un peu de vinaigre.","Servez les ailes immédiatement avec des bâtonnets de céleri et la sauce au bleu à part."],
     en:["Thoroughly dry the chicken wings, fry in hot oil 12 minutes until well browned and crisp.","Melt the butter, mix it into the hot sauce while still warm to emulsify.","Drain the fried wings, plunge them into the scorching sauce, tossing to coat well.","Prepare the blue cheese dip by mixing crumbled blue cheese, sour cream and a little vinegar.","Serve the wings immediately with celery sticks and the blue cheese dip on the side."]
     } },

{ id:'deep-dish-pizza', c:'na', lat:41.878, lon:-87.630, base:6, prep:60, cook:35, diff:2, tags:['bake','comfort','veg'],
  art:{v:'plate',bg:'#2f2a20',plate:'#e9dcc0',style:'flat',food:['#c2452c','#e0c07a','#4f8f4a'],garnish:'#7fae6a'},
  n:{fr:'Pizza deep dish',en:'Deep-dish pizza'},
  p:{fr:'Chicago, Illinois, États-Unis',en:'Chicago, Illinois, USA'},
  d:{fr:"Une pizza épaisse cuite dans un moule à haut rebord comme une tarte, montée à l'envers avec le fromage sous la sauce tomate pour l'empêcher de brûler durant les 35 minutes de cuisson nécessaires, spécialité née à Chicago dans les années 1940.",
     en:"A thick pizza baked in a high-sided pan like a pie, layered upside down with cheese under the tomato sauce to keep it from burning during the 35 minutes of baking needed, a speciality born in Chicago in the 1940s."
     },
  i:[['flour',500,'g'],['dry_yeast',7,'g'],['cornmeal',60,'g'],['olive_oil',80,'ml'],['mozzarella',400,'g'],['tomato_sauce',500,'ml'],['sausage',300,'g'],['parmesan',60,'g'],['oregano',1,'tsp']],
  s:{fr:["Pétrissez farine, semoule de maïs, levure, huile d'olive et eau tiède en une pâte souple, laissez lever 1 heure.","Étalez la pâte épaisse dans un moule à haut rebord bien huilé, en remontant sur les bords.","Disposez le fromage mozzarella en tranches directement sur la pâte.","Ajoutez la saucisse émiettée cuite, puis la sauce tomate épaisse assaisonnée d'origan par-dessus.","Enfournez 30 à 35 minutes à 220 °C jusqu'à croûte dorée, parsemez de parmesan et laissez reposer 10 minutes avant de couper."],
     en:["Knead flour, cornmeal, yeast, olive oil and warm water into a supple dough, let rise 1 hour.","Roll the thick dough into a well-oiled high-sided pan, bringing it up the sides.","Arrange sliced mozzarella directly on the dough.","Add cooked crumbled sausage, then the thick tomato sauce seasoned with oregano on top.","Bake 30 to 35 minutes at 220°C until golden crust, scatter with parmesan and let rest 10 minutes before cutting."]
     } },

{ id:'chicago-hot-dog', c:'na', lat:41.878, lon:-87.630, base:4, prep:15, cook:10, diff:1, tags:['street','beef','fast'],
  art:{v:'board',bg:'#2f2a20',plate:'#e9dcc0',style:'roll',food:['#c2452c','#4f8f4a','#e0dcc0'],garnish:'#7fae6a'},
  n:{fr:'Hot-dog de Chicago',en:'Chicago hot dog'},
  p:{fr:'Chicago, Illinois, États-Unis',en:'Chicago, Illinois, USA'},
  d:{fr:"Une saucisse de bœuf pochée nichée dans un pain aux graines de pavot, garnie d'une liste précise et intouchable de sept condiments — moutarde, oignon, relish vert vif, tomate, cornichon, piment doux et sel de céleri — jamais de ketchup.",
     en:"A poached all-beef sausage nestled in a poppy-seed bun, topped with a precise and untouchable list of seven condiments — mustard, onion, bright green relish, tomato, pickle, sport pepper and celery salt — never ketchup."
     },
  i:[['beef_sausage',4,'pc'],['poppy_seed_bun',4,'pc'],['mustard',3,'tbsp'],['onion',1,'pc'],['relish',60,'g'],['tomato',1,'pc'],['pickles',2,'pc'],['celery_salt',1,'tsp']],
  s:{fr:["Pochez les saucisses de bœuf à l'eau frémissante 6 minutes sans faire bouillir.","Faites chauffer les pains aux graines de pavot à la vapeur pour les ramollir légèrement.","Déposez chaque saucisse dans un pain, tartinez de moutarde en zigzag.","Garnissez dans l'ordre d'oignon finement haché, relish vert, quartiers de tomate, cornichon entier en lanière.","Terminez par une pincée de sel de céleri et un piment doux, servez immédiatement sans jamais ajouter de ketchup."],
     en:["Poach the beef sausages in simmering water 6 minutes without boiling.","Steam the poppy-seed buns to soften slightly.","Place each sausage in a bun, drizzle mustard in a zigzag.","Top in order with finely chopped onion, green relish, tomato wedges, a whole pickle spear.","Finish with a pinch of celery salt and a sport pepper, serve immediately, never adding ketchup."]
     } },

{ id:'crab-cakes-maryland', c:'na', lat:39.290, lon:-76.612, base:4, prep:20, cook:15, diff:2, tags:['sea','fry','festive'],
  art:{v:'plate',bg:'#2f2a20',plate:'#e9dcc0',style:'other',food:['#e0a83a','#e0c07a','#4f8f4a'],garnish:'#7fae6a'},
  n:{fr:'Crab cakes du Maryland',en:'Maryland crab cakes'},
  p:{fr:'Baltimore, Maryland, États-Unis',en:'Baltimore, Maryland, USA'},
  d:{fr:"Des galettes de chair de crabe bleu de la baie de Chesapeake, à peine liées de chapelure et de mayonnaise pour laisser dominer le crabe, poêlées jusqu'à dorées, assaisonnées du mélange épicé Old Bay emblématique du Maryland.",
     en:"Patties of Chesapeake Bay blue crab meat, barely bound with breadcrumbs and mayonnaise to let the crab dominate, pan-fried until golden, seasoned with the Old Bay spice blend emblematic of Maryland."
     },
  i:[['crab_meat',500,'g'],['breadcrumbs',60,'g'],['mayonnaise',60,'ml'],['egg',1,'pc'],['old_bay_seasoning',1,'tbsp'],['dijon_mustard',1,'tsp'],['parsley',1,'bunch'],['butter',40,'g']],
  s:{fr:["Vérifiez soigneusement la chair de crabe pour ôter tout fragment de carapace.","Mélangez délicatement avec chapelure, mayonnaise, œuf, moutarde et assaisonnement Old Bay, sans trop travailler pour garder de gros morceaux.","Formez des galettes épaisses à la main, réservez au frais 30 minutes pour qu'elles se tiennent.","Faites dorer les galettes dans le beurre à feu moyen, 4 minutes de chaque côté.","Parsemez de persil frais et servez avec un quartier de citron et une sauce tartare."],
     en:["Carefully check the crab meat to remove any shell fragments.","Gently mix with breadcrumbs, mayonnaise, egg, mustard and Old Bay seasoning, without overworking to keep large lumps.","Shape thick patties by hand, chill 30 minutes so they hold together.","Brown the patties in butter over medium heat, 4 minutes per side.","Scatter with fresh parsley and serve with a lemon wedge and tartar sauce."]
     } },

{ id:'shrimp-and-grits', c:'na', lat:32.777, lon:-79.931, base:4, prep:15, cook:30, diff:1, tags:['sea','comfort','breakfast'],
  art:{v:'bowl',bg:'#2f2a20',plate:'#e9dcc0',style:'stew',food:['#c2452c','#e0c07a','#4f8f4a'],garnish:'#7fae6a'},
  n:{fr:'Crevettes et grits',en:'Shrimp and grits'},
  p:{fr:'Charleston, Caroline du Sud, États-Unis',en:'Charleston, South Carolina, USA'},
  d:{fr:"Une bouillie de maïs crémeuse au fromage et au beurre, surmontée de crevettes sautées au bacon et aux épices cajun, plat de pêcheurs du Lowcountry élevé en quelques décennies au rang de spécialité gastronomique nationale.",
     en:"A creamy cheese-and-butter corn porridge, topped with shrimp sautéed with bacon and Cajun spices, a Lowcountry fishermen's dish elevated in a few decades to national gastronomic speciality."
     },
  i:[['grits',200,'g'],['whole_milk',600,'ml'],['cheddar_cheese',150,'g'],['butter',60,'g'],['shrimp',500,'g'],['smoked_bacon',150,'g'],['garlic',3,'clove'],['cajun_seasoning',1,'tbsp'],['scallion',3,'pc']],
  s:{fr:["Portez le lait à ébullition, versez les grits en pluie en fouettant pour éviter les grumeaux.","Laissez cuire à feu doux 20 minutes en remuant régulièrement jusqu'à crémeux, incorporez fromage cheddar et beurre.","Faites revenir le bacon en dés jusqu'à croustillant, réservez.","Faites sauter les crevettes assaisonnées de cajun et d'ail dans la graisse de bacon jusqu'à roses, 4 minutes.","Servez les crevettes et le bacon sur les grits crémeux, parsemez de ciboule ciselée."],
     en:["Bring the milk to a boil, whisk in the grits in a stream to avoid lumps.","Cook over low heat 20 minutes, stirring regularly, until creamy, stir in cheddar cheese and butter.","Fry the diced bacon until crisp, set aside.","Sauté the shrimp seasoned with Cajun spice and garlic in the bacon fat until pink, 4 minutes.","Serve the shrimp and bacon over the creamy grits, scatter with chopped scallion."]
     } },

{ id:'kentucky-hot-brown', c:'na', lat:38.253, lon:-85.759, base:4, prep:15, cook:20, diff:1, tags:['comfort','poultry','bake'],
  art:{v:'plate',bg:'#2f2a20',plate:'#e9dcc0',style:'other',food:['#e0c07a','#c2452c','#8a3a24'],garnish:'#7fae6a'},
  n:{fr:'Kentucky Hot Brown',en:'Kentucky Hot Brown'},
  p:{fr:'Louisville, Kentucky, États-Unis',en:'Louisville, Kentucky, USA'},
  d:{fr:"Un sandwich ouvert de dinde noyé sous une sauce mornay au fromage, gratiné au four avec tranches de bacon croustillant et tomate, inventé dans les années 1920 par un chef d'hôtel de Louisville pour nourrir les danseurs affamés après minuit.",
     en:"An open turkey sandwich drowned in cheesy mornay sauce, broiled with crispy bacon slices and tomato, invented in the 1920s by a Louisville hotel chef to feed hungry dancers after midnight."
     },
  i:[['turkey_breast',500,'g'],['white_bread',4,'slice'],['gruyere_cheese',150,'g'],['butter',40,'g'],['flour',40,'g'],['whole_milk',400,'ml'],['smoked_bacon',150,'g'],['tomato',2,'pc'],['parmesan',40,'g']],
  s:{fr:["Faites un roux avec beurre et farine, mouillez de lait chaud en fouettant jusqu'à sauce lisse et épaisse.","Incorporez le gruyère râpé hors du feu jusqu'à fondu, assaisonnez.","Disposez une tranche de pain dans un plat individuel, couvrez de tranches épaisses de dinde.","Nappez généreusement de sauce mornay, ajoutez tranches de tomate et parmesan râpé par-dessus.","Enfournez sous le gril quelques minutes jusqu'à doré et bouillonnant, garnissez de bacon croustillant et servez immédiatement brûlant."],
     en:["Make a roux with butter and flour, moisten with hot milk, whisking until a smooth thick sauce forms.","Stir in the grated gruyère off the heat until melted, season.","Place a slice of bread in an individual dish, cover with thick turkey slices.","Coat generously with mornay sauce, add tomato slices and grated parmesan on top.","Broil a few minutes until golden and bubbling, garnish with crispy bacon and serve immediately, piping hot."]
     } },

{ id:'chicken-and-waffles', c:'na', lat:40.811, lon:-73.943, base:4, prep:30, cook:30, diff:2, tags:['fry','poultry','sweet'],
  art:{v:'plate',bg:'#2f2a20',plate:'#e9dcc0',style:'other',food:['#e0c07a','#c9924a','#f0e2c0'],garnish:'#7fae6a'},
  n:{fr:'Poulet et gaufres',en:'Chicken and waffles'},
  p:{fr:'Harlem, New York, États-Unis',en:'Harlem, New York, USA'},
  d:{fr:"Du poulet frit extra-croustillant posé directement sur une gaufre moelleuse, arrosé de sirop d'érable qui vient contraster sucré-salé, plat né dans les clubs de jazz de Harlem où l'on mangeait entre le dîner tardif et le petit-déjeuner.",
     en:"Extra-crispy fried chicken set directly on a soft waffle, drizzled with maple syrup for a sweet-savoury contrast, a dish born in Harlem's jazz clubs where people ate between late dinner and breakfast."
     },
  i:[['chicken',1,'kg'],['buttermilk',400,'ml'],['flour',300,'g'],['cayenne_pepper',1,'tsp'],['egg',2,'pc'],['whole_milk',350,'ml'],['butter',80,'g'],['maple_syrup',150,'ml'],['frying_oil',1,'l']],
  s:{fr:["Faites mariner le poulet dans le babeurre au moins 4 heures.","Égouttez, passez dans la farine assaisonnée de cayenne, faites frire à 175 °C 15 minutes jusqu'à doré et croustillant.","Préparez la pâte à gaufre en mélangeant farine, œufs, lait et beurre fondu.","Faites cuire les gaufres dans un gaufrier chaud jusqu'à dorées et croustillantes.","Déposez le poulet frit sur les gaufres chaudes, arrosez généreusement de sirop d'érable et servez immédiatement."],
     en:["Marinate the chicken in buttermilk at least 4 hours.","Drain, dredge in flour seasoned with cayenne, fry at 175°C 15 minutes until golden and crisp.","Prepare the waffle batter by mixing flour, eggs, milk and melted butter.","Cook the waffles in a hot waffle iron until golden and crisp.","Place the fried chicken on the warm waffles, drizzle generously with maple syrup and serve immediately."]
     } },

{ id:'new-york-cheesecake', c:'na', lat:40.713, lon:-74.006, base:10, prep:30, cook:60, diff:2, tags:['bake','sweet','festive'],
  art:{v:'plate',bg:'#2f2a20',plate:'#e9dcc0',style:'other',food:['#f0e2c0','#e0c07a','#c9924a'],garnish:'#7fae6a'},
  n:{fr:'Cheesecake new-yorkais',en:'New York cheesecake'},
  p:{fr:'New York, États-Unis',en:'New York, USA'},
  d:{fr:"Un gâteau au fromage dense et lisse à base de cream cheese, cuit au bain-marie sur une fine croûte de biscuits émiettés, dont la texture haute et compacte tranche radicalement avec les versions plus légères d'Europe.",
     en:"A dense, smooth cheesecake made with cream cheese, baked in a water bath on a thin crumbled biscuit crust, whose tall, compact texture radically contrasts with lighter European versions."
     },
  i:[['cream_cheese',900,'g'],['sugar',250,'g'],['egg',4,'pc'],['heavy_cream',150,'ml'],['digestive_biscuits',200,'g'],['butter',80,'g'],['vanilla',1,'tsp'],['lemon',1,'pc']],
  s:{fr:["Mixez les biscuits en miettes fines, mélangez avec le beurre fondu et pressez au fond d'un moule à charnière.","Battez le cream cheese jusqu'à lisse, incorporez le sucre progressivement.","Ajoutez les œufs un par un en battant peu pour éviter d'incorporer trop d'air, puis la crème, la vanille et le zeste de citron.","Versez sur la croûte, enfournez au bain-marie 55 minutes à 160 °C jusqu'à peine tremblant au centre.","Laissez refroidir dans le four éteint porte entrouverte, puis réfrigérez au moins 6 heures avant de démouler."],
     en:["Blitz the biscuits into fine crumbs, mix with melted butter and press into the base of a springform pan.","Beat the cream cheese until smooth, gradually add the sugar.","Add the eggs one at a time, beating minimally to avoid incorporating too much air, then the cream, vanilla and lemon zest.","Pour over the crust, bake in a water bath 55 minutes at 160°C until barely wobbly in the centre.","Let cool in the turned-off oven with the door ajar, then chill at least 6 hours before unmoulding."]
     } },

{ id:'pastrami-on-rye', c:'na', lat:40.750, lon:-73.994, base:4, prep:1440, cook:240, diff:3, tags:['beef','street','fast'],
  art:{v:'board',bg:'#2f2a20',plate:'#e9dcc0',style:'roll',food:['#8a3a24','#e0dcc0','#c9924a'],garnish:'#7fae6a'},
  n:{fr:'Pastrami on rye',en:'Pastrami on rye'},
  p:{fr:'Manhattan, New York, États-Unis',en:'Manhattan, New York, USA'},
  d:{fr:"De la poitrine de bœuf salée en saumure épicée puis fumée longuement et cuite à la vapeur, tranchée en épaisseur généreuse et empilée haut entre deux tranches de pain de seigle, héritage des delicatessens juifs d'Europe de l'Est.",
     en:"Beef brisket cured in a spiced brine then long-smoked and steamed, sliced thick and piled high between two slices of rye bread, a legacy of Eastern European Jewish delicatessens."
     },
  i:[['beef_brisket',1.5,'kg'],['coarse_salt',150,'g'],['black_peppercorns',60,'g'],['coriander_seeds',40,'g'],['garlic',6,'clove'],['rye_bread',8,'slice'],['mustard',60,'g'],['pickles',4,'pc']],
  s:{fr:["Frottez la poitrine de bœuf de gros sel, ail écrasé et épices, laissez saumurer au frais 5 jours en retournant chaque jour.","Rincez soigneusement, enrobez d'une croûte épaisse de poivre et coriandre concassés.","Fumez à froid plusieurs heures puis à chaud jusqu'à ce qu'une croûte noire se forme.","Faites cuire à la vapeur 3 heures jusqu'à extrêmement tendre.","Tranchez très finement contre le grain, empilez généreusement entre deux tranches de pain de seigle avec moutarde, servez avec des cornichons."],
     en:["Rub the brisket with coarse salt, crushed garlic and spices, cure chilled 5 days, turning daily.","Rinse thoroughly, coat with a thick crust of cracked pepper and coriander.","Cold-smoke several hours then hot-smoke until a black crust forms.","Steam 3 hours until extremely tender.","Slice very thin against the grain, pile generously between two slices of rye bread with mustard, serve with pickles."]
     } },

{ id:'cuban-sandwich-miami', c:'na', lat:25.762, lon:-80.192, base:4, prep:20, cook:15, diff:1, tags:['pork','street','fast'],
  art:{v:'board',bg:'#2f2a20',plate:'#e9dcc0',style:'roll',food:['#e0c07a','#8a3a24','#e0dcc0'],garnish:'#7fae6a'},
  n:{fr:'Sandwich cubain de Miami',en:'Miami Cuban sandwich'},
  p:{fr:'Miami, Floride, États-Unis',en:'Miami, Florida, USA'},
  d:{fr:"Du porc rôti, jambon, fromage suisse, cornichon et moutarde pressés dans un pain cubain jusqu'à ce que le fromage fonde et que la croûte devienne croustillante, sandwich forgé par les communautés cubaines de Ybor City et Miami.",
     en:"Roast pork, ham, Swiss cheese, pickle and mustard pressed in Cuban bread until the cheese melts and the crust turns crisp, a sandwich forged by the Cuban communities of Ybor City and Miami."
     },
  i:[['pork_shoulder',400,'g'],['ham',200,'g'],['swiss_cheese',150,'g'],['pickles',4,'pc'],['mustard',3,'tbsp'],['cuban_bread',4,'pc'],['butter',40,'g']],
  s:{fr:["Faites rôtir ou réchauffer le porc effiloché ou tranché.","Fendez le pain cubain en deux, tartinez de moutarde des deux côtés.","Garnissez de porc, jambon, fromage suisse en tranches et cornichons en lanières.","Beurrez l'extérieur du sandwich, pressez dans une plancha ou une presse à panini chaude.","Faites cuire 5 minutes en pressant jusqu'à ce que le fromage fonde et le pain soit croustillant et aplati, coupez en diagonale et servez chaud."],
     en:["Roast or reheat the shredded or sliced pork.","Split the Cuban bread in two, spread mustard on both sides.","Fill with pork, ham, sliced Swiss cheese and pickle strips.","Butter the outside of the sandwich, press in a hot plancha or panini press.","Cook 5 minutes while pressing until the cheese melts and the bread is crisp and flattened, cut diagonally and serve hot."]
     } },

{ id:'key-lime-pie', c:'na', lat:24.556, lon:-81.780, base:8, prep:30, cook:15, diff:1, tags:['sweet','bake','fresh'],
  art:{v:'plate',bg:'#2f2a20',plate:'#e9dcc0',style:'other',food:['#e0c07a','#f0e2c0','#4f8f4a'],garnish:'#7fae6a'},
  n:{fr:'Key lime pie',en:'Key lime pie'},
  p:{fr:'Key West, Floride, États-Unis',en:'Key West, Florida, USA'},
  d:{fr:"Une tarte acidulée au jus des petits citrons verts key lime des Keys de Floride, mêlé au lait concentré sucré pour épaissir sans cuisson complexe, sur une croûte de biscuits Graham, dessert typique de l'archipel tropical.",
     en:"A tangy pie made with the juice of small key limes from the Florida Keys, mixed with sweetened condensed milk to thicken without complex cooking, on a Graham cracker crust, a typical dessert of the tropical archipelago."
     },
  i:[['graham_crackers',200,'g'],['butter',80,'g'],['condensed_milk',800,'ml'],['key_lime_juice',180,'ml'],['egg_yolk',4,'pc'],['heavy_cream',200,'ml']],
  s:{fr:["Mixez les biscuits Graham en miettes fines, mélangez au beurre fondu et pressez dans un moule à tarte.","Enfournez la croûte 10 minutes à 180 °C, laissez refroidir.","Fouettez le lait concentré sucré avec les jaunes d'œufs et le jus de citron vert jusqu'à épaissi et lisse.","Versez sur la croûte refroidie, enfournez 15 minutes à 160 °C jusqu'à à peine pris.","Laissez refroidir puis réfrigérer au moins 3 heures, servez avec de la crème fouettée."],
     en:["Blitz the Graham crackers into fine crumbs, mix with melted butter and press into a pie pan.","Bake the crust 10 minutes at 180°C, let cool.","Whisk the sweetened condensed milk with the egg yolks and key lime juice until thick and smooth.","Pour onto the cooled crust, bake 15 minutes at 160°C until barely set.","Let cool then chill at least 3 hours, serve with whipped cream."]
     } },

{ id:'sonoran-hot-dog', c:'na', lat:32.222, lon:-110.975, base:4, prep:15, cook:15, diff:1, tags:['street','pork','spicy'],
  art:{v:'board',bg:'#2f2a20',plate:'#e9dcc0',style:'roll',food:['#c2452c','#e0a83a','#4f8f4a'],garnish:'#7fae6a'},
  n:{fr:'Hot-dog sonoran',en:'Sonoran hot dog'},
  p:{fr:'Tucson, Arizona, États-Unis',en:'Tucson, Arizona, USA'},
  d:{fr:"Une saucisse enroulée de bacon et grillée jusqu'à croustillante, nichée dans un pain moelleux façon bolillo et couverte de haricots pinto, oignon, tomate et une sauce jalapeño crémeuse, spécialité née à la frontière avec le Mexique.",
     en:"A sausage wrapped in bacon and grilled until crisp, nestled in a soft bolillo-style bun and covered with pinto beans, onion, tomato and a creamy jalapeño sauce, a speciality born on the Mexican border."
     },
  i:[['beef_sausage',4,'pc'],['smoked_bacon',4,'slice'],['bolillo_bread',4,'pc'],['pinto_beans',200,'g'],['onion',1,'pc'],['tomato',2,'pc'],['jalapeno',2,'pc'],['mayonnaise',80,'ml']],
  s:{fr:["Enroulez chaque saucisse d'une tranche de bacon en spirale serrée.","Faites griller à feu moyen en tournant régulièrement jusqu'à ce que le bacon soit croustillant, environ 10 minutes.","Réchauffez les haricots pinto en purée grossière.","Mixez jalapeño et mayonnaise pour la sauce crémeuse épicée.","Garnissez le pain chaud de haricots, saucisse enroulée de bacon, oignon et tomate en dés, terminez d'un filet de sauce jalapeño."],
     en:["Wrap each sausage in a slice of bacon in a tight spiral.","Grill over medium heat, turning regularly, until the bacon is crisp, about 10 minutes.","Warm the pinto beans, roughly mashed.","Blend jalapeño and mayonnaise for the creamy spicy sauce.","Fill the warm bun with beans, bacon-wrapped sausage, diced onion and tomato, finish with a drizzle of jalapeño sauce."]
     } },

{ id:'fish-tacos-baja', c:'na', lat:32.716, lon:-117.161, base:4, prep:20, cook:15, diff:1, tags:['sea','fry','fresh'],
  art:{v:'board',bg:'#26333c',plate:'#e9dcc0',style:'roll',food:['#e0c07a','#4f8f4a','#e0dcc0'],garnish:'#7fae6a'},
  n:{fr:'Tacos au poisson façon Baja',en:'Baja-style fish tacos'},
  p:{fr:'San Diego, Californie, États-Unis',en:'San Diego, California, USA'},
  d:{fr:"Du poisson blanc pané en bière puis frit croustillant, roulé dans une tortilla de maïs chaude avec chou finement émincé et sauce crémeuse épicée, plat né de la pêche transfrontalière entre San Diego et la Basse-Californie mexicaine.",
     en:"White fish battered in beer then fried crisp, rolled in a warm corn tortilla with finely shredded cabbage and a creamy spicy sauce, a dish born from cross-border fishing between San Diego and Mexican Baja California."
     },
  i:[['white_fish',600,'g'],['beer',250,'ml'],['flour',200,'g'],['cabbage',300,'g'],['tortilla',8,'pc'],['mayonnaise',100,'ml'],['chipotle',2,'pc'],['lime',2,'pc'],['frying_oil',500,'ml']],
  s:{fr:["Mélangez farine et bière fraîche en une pâte à frire légère et mousseuse.","Coupez le poisson en lanières, trempez-les dans la pâte à bière.","Faites frire dans l'huile chaude à 180 °C jusqu'à doré et croustillant, égouttez sur papier absorbant.","Mixez mayonnaise et chipotle pour la sauce crémeuse épicée.","Garnissez les tortillas chaudes de chou émincé, poisson frit et sauce chipotle, arrosez d'un filet de citron vert."],
     en:["Mix flour and cold beer into a light, foamy batter.","Cut the fish into strips, dip in the beer batter.","Fry in hot oil at 180°C until golden and crisp, drain on paper towel.","Blend mayonnaise and chipotle for the creamy spicy sauce.","Fill the warm tortillas with shredded cabbage, fried fish and chipotle sauce, drizzle with a splash of lime."]
     } },

{ id:'cioppino', c:'na', lat:37.775, lon:-122.419, base:6, prep:30, cook:40, diff:2, tags:['sea','stew','festive'],
  art:{v:'pot',bg:'#26333c',plate:'#e9dcc0',style:'stew',food:['#c2452c','#e0a83a','#4f8f4a'],garnish:'#7fae6a'},
  n:{fr:'Cioppino',en:'Cioppino'},
  p:{fr:'San Francisco, Californie, États-Unis',en:'San Francisco, California, USA'},
  d:{fr:"Un ragoût de poissons et fruits de mer variés dans un bouillon tomaté au vin blanc, né des pêcheurs immigrés italiens de Fisherman's Wharf qui mettaient en commun les invendus du jour dans une même grande marmite.",
     en:"A stew of assorted fish and shellfish in a tomato and white wine broth, born from Fisherman's Wharf's Italian immigrant fishermen who pooled the day's unsold catch into one big shared pot."
     },
  i:[['clams',400,'g'],['shrimp',300,'g'],['crab',400,'g'],['white_fish',300,'g'],['mussels',300,'g'],['tomato',5,'pc'],['white_wine',200,'ml'],['onion',2,'pc'],['garlic',5,'clove'],['fish_broth',400,'ml']],
  s:{fr:["Faites suer oignon et ail émincés dans l'huile d'olive jusqu'à translucides.","Ajoutez tomate concassée et vin blanc, laissez mijoter 15 minutes en une base parfumée.","Ajoutez le bouillon de poisson, portez à petits frémissements.","Ajoutez le poisson en morceaux d'abord, puis crabe, crevettes, moules et palourdes selon leur temps de cuisson.","Laissez mijoter 12 minutes jusqu'à ce que tous les coquillages soient ouverts, servez brûlant avec du pain croustillant."],
     en:["Sweat sliced onion and garlic in olive oil until translucent.","Add crushed tomato and white wine, simmer 15 minutes into a fragrant base.","Add the fish broth, bring to a gentle simmer.","Add the fish in chunks first, then crab, shrimp, mussels and clams according to their cooking time.","Simmer 12 minutes until all the shellfish have opened, serve scalding with crusty bread."]
     } },

{ id:'wisconsin-cheese-curds', c:'na', lat:43.073, lon:-89.401, base:6, prep:15, cook:10, diff:1, tags:['fry','veg','street'],
  art:{v:'board',bg:'#2f2a20',plate:'#e9dcc0',style:'other',food:['#f0e2c0','#e0c07a','#4f8f4a'],garnish:'#7fae6a'},
  n:{fr:'Cheese curds frits du Wisconsin',en:'Wisconsin fried cheese curds'},
  p:{fr:'Madison, Wisconsin, États-Unis',en:'Madison, Wisconsin, USA'},
  d:{fr:"De petits grains de fromage frais couinant sous la dent, panés puis frits jusqu'à former une croûte dorée qui emprisonne l'intérieur fondant, spécialité de la foire du comté du Wisconsin, premier État laitier des États-Unis.",
     en:"Small squeaky curds of fresh cheese, battered then fried until forming a golden crust that traps a molten interior, a Wisconsin county fair speciality from America's leading dairy state."
     },
  i:[['cheese_curds',400,'g'],['flour',150,'g'],['egg',2,'pc'],['whole_milk',150,'ml'],['breadcrumbs',150,'g'],['frying_oil',1,'l'],['paprika',1,'tsp']],
  s:{fr:["Sortez les cheese curds du réfrigérateur 20 minutes avant de les paner pour qu'ils soient à température ambiante.","Préparez trois assiettes : farine, œuf battu au lait, chapelure assaisonnée de paprika.","Passez chaque grain de fromage dans la farine puis l'œuf puis la chapelure, en pressant bien pour faire adhérer.","Faites frire dans l'huile chaude à 190 °C par petites quantités, seulement 1 à 2 minutes jusqu'à dorés sans laisser le fromage fondre entièrement.","Égouttez sur papier absorbant et servez immédiatement brûlant, le fromage devant encore couiner sous la dent."],
     en:["Take the cheese curds out of the fridge 20 minutes before breading so they reach room temperature.","Prepare three plates: flour, egg beaten with milk, breadcrumbs seasoned with paprika.","Dredge each curd in flour then egg then breadcrumbs, pressing well to adhere.","Fry in hot oil at 190°C in small batches, only 1 to 2 minutes until golden without letting the cheese fully melt.","Drain on paper towel and serve immediately, piping hot, the cheese should still squeak."]
     } },

{ id:'minnesota-hotdish', c:'na', lat:44.978, lon:-93.265, base:8, prep:20, cook:40, diff:1, tags:['bake','beef','comfort'],
  art:{v:'plate',bg:'#2f2a20',plate:'#e9dcc0',style:'other',food:['#e0dcc0','#8a3a24','#4f8f4a'],garnish:'#7fae6a'},
  n:{fr:'Hotdish du Minnesota',en:'Minnesota hotdish'},
  p:{fr:'Minneapolis, Minnesota, États-Unis',en:'Minneapolis, Minnesota, USA'},
  d:{fr:"Un gratin réconfortant de bœuf haché, haricots verts et soupe de champignons en conserve, couronné de chips d'oignon croustillantes, plat de congrégation religieuse et de repas partagés propre à la culture scandinave-américaine du Midwest.",
     en:"A comforting bake of ground beef, green beans and canned mushroom soup, topped with crispy onion crisps, a church-potluck dish typical of the Scandinavian-American culture of the Midwest."
     },
  i:[['ground_beef',600,'g'],['green_beans',400,'g'],['mushroom_soup',400,'ml'],['onion',1,'pc'],['fried_onions',100,'g'],['cheddar_cheese',150,'g'],['potato',4,'pc']],
  s:{fr:["Faites revenir le bœuf haché avec l'oignon émincé jusqu'à bien coloré.","Disposez le bœuf cuit au fond d'un grand plat allant au four.","Couvrez de haricots verts puis de soupe de champignons étalée uniformément.","Ajoutez pomme de terre en fines rondelles ou en purée sur le dessus, parsemez de fromage râpé.","Enfournez 30 minutes à 190 °C, couronnez de chips d'oignon croustillantes pour les 10 dernières minutes."],
     en:["Fry the ground beef with sliced onion until well browned.","Arrange the cooked beef at the bottom of a large oven dish.","Cover with green beans then mushroom soup spread evenly.","Add potato in thin rounds or mashed on top, scatter with grated cheese.","Bake 30 minutes at 190°C, crown with crispy onion crisps for the last 10 minutes."]
     } },

{ id:'detroit-coney-dog', c:'na', lat:42.331, lon:-83.046, base:4, prep:15, cook:30, diff:1, tags:['street','beef','fast'],
  art:{v:'board',bg:'#2f2a20',plate:'#e9dcc0',style:'roll',food:['#c2452c','#8a3a24','#e0c07a'],garnish:'#7fae6a'},
  n:{fr:'Coney dog de Detroit',en:'Detroit coney dog'},
  p:{fr:'Detroit, Michigan, États-Unis',en:'Detroit, Michigan, USA'},
  d:{fr:"Une saucisse noyée sous un chili de bœuf sans haricots, moutarde et oignon cru finement haché, né de la rivalité séculaire entre deux restaurants voisins du centre-ville de Detroit tenus par des immigrés grecs et macédoniens.",
     en:"A sausage drowned under bean-free beef chili, mustard and finely chopped raw onion, born from a century-old rivalry between two neighbouring downtown Detroit restaurants run by Greek and Macedonian immigrants."
     },
  i:[['beef_sausage',4,'pc'],['ground_beef',300,'g'],['tomato_paste',3,'tbsp'],['cumin',1,'tsp'],['chili_powder',1,'tbsp'],['hot_dog_bun',4,'pc'],['mustard',3,'tbsp'],['onion',1,'pc']],
  s:{fr:["Faites revenir le bœuf haché très finement jusqu'à ce qu'il soit presque en poudre, sans le laisser croustiller.","Ajoutez concentré de tomate, cumin et chili en poudre, mouillez légèrement et laissez mijoter 20 minutes en un chili épais sans haricots.","Faites pocher ou griller les saucisses jusqu'à chaudes.","Déposez chaque saucisse dans un pain, couvrez généreusement de chili de bœuf chaud.","Terminez par un trait de moutarde et de l'oignon cru finement haché, servez immédiatement avec une fourchette."],
     en:["Fry the beef very finely until almost powder-like, without letting it crisp.","Add tomato paste, cumin and chili powder, moisten lightly and simmer 20 minutes into a thick, bean-free chili.","Poach or grill the sausages until hot.","Place each sausage in a bun, cover generously with hot beef chili.","Finish with a squiggle of mustard and finely chopped raw onion, serve immediately with a fork."]
     } },

{ id:'beignets-nola', c:'na', lat:29.951, lon:-90.072, base:12, prep:90, cook:15, diff:2, tags:['fry','sweet','breakfast'],
  art:{v:'board',bg:'#2f2a20',plate:'#e9dcc0',style:'other',food:['#f0e2c0','#e0c07a','#e0dcc0'],garnish:'#7fae6a'},
  n:{fr:'Beignets du Café du Monde',en:'Beignets, Café du Monde style'},
  p:{fr:'La Nouvelle-Orléans, Louisiane, États-Unis',en:'New Orleans, Louisiana, USA'},
  d:{fr:"Des carrés de pâte levée frits jusqu'à gonfler en coussinets dorés, ensevelis sous une neige épaisse de sucre glace, dessert français transformé en institution de La Nouvelle-Orléans, traditionnellement mangé avec un café-chicorée au lait.",
     en:"Squares of yeasted dough fried until puffing into golden pillows, buried under a thick snow of powdered sugar, a French dessert turned New Orleans institution, traditionally eaten with chicory coffee and milk."
     },
  i:[['flour',500,'g'],['dry_yeast',7,'g'],['whole_milk',200,'ml'],['egg',1,'pc'],['sugar',60,'g'],['butter',60,'g'],['powdered_sugar',150,'g'],['frying_oil',1,'l']],
  s:{fr:["Délayez la levure dans le lait tiède, laissez mousser 10 minutes.","Pétrissez avec farine, œuf, sucre, beurre fondu et sel en une pâte souple, laissez lever 1 heure.","Étalez la pâte à 1 cm d'épaisseur, découpez en carrés réguliers d'environ 8 cm.","Faites frire dans l'huile chaude à 180 °C jusqu'à bien gonflés et dorés des deux côtés.","Égouttez et couvrez immédiatement d'une épaisse couche de sucre glace, servez chaud."],
     en:["Dissolve the yeast in warm milk, let foam 10 minutes.","Knead with flour, egg, sugar, melted butter and salt into a supple dough, let rise 1 hour.","Roll the dough 1 cm thick, cut into even squares about 8 cm.","Fry in hot oil at 180°C until well puffed and golden on both sides.","Drain and immediately cover with a thick layer of powdered sugar, serve hot."]
     } },

{ id:'shoofly-pie', c:'na', lat:40.038, lon:-76.306, base:8, prep:20, cook:40, diff:1, tags:['bake','sweet','comfort'],
  art:{v:'plate',bg:'#2f2a20',plate:'#e9dcc0',style:'other',food:['#8a3a24','#e0c07a','#c9924a'],garnish:'#7fae6a'},
  n:{fr:'Shoofly pie',en:'Shoofly pie'},
  p:{fr:'Lancaster, Pennsylvanie, États-Unis',en:'Lancaster, Pennsylvania, USA'},
  d:{fr:"Une tarte à la mélasse extrêmement sucrée couronnée d'un crumble de farine et de beurre, héritage des communautés amish et mennonites de Pennsylvanie, dont le nom viendrait des mouches qu'il fallait chasser de la tarte refroidissant sur le rebord de fenêtre.",
     en:"An extremely sweet molasses pie topped with a flour-and-butter crumble, a legacy of Pennsylvania's Amish and Mennonite communities, whose name allegedly comes from the flies that had to be shooed from the pie cooling on the windowsill."
     },
  i:[['flour',300,'g'],['molasses',300,'ml'],['baking_soda',1,'tsp'],['brown_sugar',150,'g'],['butter',100,'g'],['egg',1,'pc'],['pie_crust',1,'pc'],['hot_water',200,'ml']],
  s:{fr:["Mélangez farine, sucre roux et beurre froid du bout des doigts jusqu'à obtenir un crumble grossier.","Délayez la mélasse, le bicarbonate et l'œuf dans l'eau chaude jusqu'à homogène.","Foncez un moule à tarte de pâte brisée, versez la moitié du crumble au fond.","Versez le mélange à la mélasse par-dessus, couvrez du reste du crumble.","Enfournez 35 minutes à 190 °C jusqu'à ce que le centre soit à peine tremblant, laissez refroidir avant de servir."],
     en:["Mix flour, brown sugar and cold butter with fingertips into a coarse crumble.","Dissolve the molasses, baking soda and egg in hot water until smooth.","Line a pie pan with shortcrust pastry, pour half the crumble into the bottom.","Pour the molasses mixture over the top, cover with the remaining crumble.","Bake 35 minutes at 190°C until the centre barely wobbles, let cool before serving."]
     } },

{ id:'peach-cobbler-georgia', c:'na', lat:33.749, lon:-84.388, base:8, prep:20, cook:45, diff:1, tags:['bake','sweet','fruit'],
  art:{v:'plate',bg:'#2f2a20',plate:'#e9dcc0',style:'other',food:['#e0a83a','#e0c07a','#f0e2c0'],garnish:'#7fae6a'},
  n:{fr:'Cobbler à la pêche de Géorgie',en:'Georgia peach cobbler'},
  p:{fr:'Atlanta, Géorgie, États-Unis',en:'Atlanta, Georgia, USA'},
  d:{fr:"Des pêches mûres et juteuses de l'État surnommé Peach State, mijotées avec sucre et cannelle sous une pâte à biscuit qui gonfle en cuisant en un couvercle irrégulier et doré, dessert de fin d'été servi tiède avec une boule de glace vanille.",
     en:"Ripe, juicy peaches from the state nicknamed the Peach State, simmered with sugar and cinnamon under a biscuit dough that puffs while baking into an irregular golden lid, a late-summer dessert served warm with a scoop of vanilla ice cream."
     },
  i:[['peach',8,'pc'],['sugar',200,'g'],['cinnamon',1,'tsp'],['flour',250,'g'],['butter',120,'g'],['baking_powder',2,'tsp'],['whole_milk',200,'ml'],['vanilla',1,'tsp']],
  s:{fr:["Épluchez et tranchez les pêches, mélangez avec la moitié du sucre et la cannelle, laissez macérer 15 minutes.","Disposez les pêches et leur jus dans un plat à gratin beurré.","Mélangez farine, reste du sucre, levure chimique, beurre fondu, lait et vanille en une pâte à biscuit épaisse.","Versez la pâte par-dessus les pêches sans l'étaler complètement, laissant apparaître des zones de fruit.","Enfournez 40 minutes à 190 °C jusqu'à doré et bouillonnant, servez tiède avec une boule de glace vanille."],
     en:["Peel and slice the peaches, mix with half the sugar and cinnamon, let macerate 15 minutes.","Arrange the peaches and their juice in a buttered baking dish.","Mix flour, remaining sugar, baking powder, melted butter, milk and vanilla into a thick biscuit batter.","Pour the batter over the peaches without spreading it completely, leaving some fruit exposed.","Bake 40 minutes at 190°C until golden and bubbling, serve warm with a scoop of vanilla ice cream."]
     } },

{ id:'king-crab-alaska', c:'na', lat:61.218, lon:-149.900, base:4, prep:10, cook:15, diff:1, tags:['sea','festive','fast'],
  art:{v:'plate',bg:'#26333c',plate:'#e9dcc0',style:'other',food:['#c2452c','#e0dcc0','#e0a83a'],garnish:'#7fae6a'},
  n:{fr:"Crabe royal d'Alaska",en:'Alaska king crab'},
  p:{fr:'Anchorage, Alaska, États-Unis',en:'Anchorage, Alaska, USA'},
  d:{fr:"D'énormes pattes de crabe royal aux eaux glacées de l'Alaska, déjà précuites en mer sur les bateaux-usines dès la capture, simplement réchauffées à la vapeur et servies avec du beurre fondu, pêche parmi les plus dangereuses au monde.",
     en:"Enormous king crab legs from Alaska's icy waters, already precooked at sea on factory ships right after capture, simply reheated by steaming and served with melted butter, a catch among the most dangerous in the world."
     },
  i:[['king_crab_legs',1.5,'kg'],['butter',150,'g'],['lemon',2,'pc'],['garlic',3,'clove'],['parsley',1,'bunch']],
  s:{fr:["Sortez les pattes de crabe royal, déjà précuites, du congélateur pour les décongeler légèrement.","Faites chauffer une grande marmite d'eau avec un panier vapeur.","Faites réchauffer les pattes à la vapeur 8 à 10 minutes jusqu'à bien chaudes à cœur.","Faites fondre le beurre avec l'ail écrasé et un peu de jus de citron.","Fendez les carapaces avec un casse-noix, servez avec le beurre à l'ail chaud et des quartiers de citron."],
     en:["Take the already precooked king crab legs out of the freezer to thaw slightly.","Heat a large pot of water with a steamer basket.","Steam the legs 8 to 10 minutes until heated through.","Melt the butter with crushed garlic and a little lemon juice.","Crack the shells with a nutcracker, serve with the warm garlic butter and lemon wedges."]
     } }
];
